mapper.select:
select *
from cr_single_room


        business_template_id = #{business_template_id}

    and

        user_id = #{user_id}

select T1.resource_id, T1.name, T1.description, T1.difficulty, T2.sub_type, T2.pre_skills, T2.train_skills, T2.duration_time, R1.start_time, R1.training_record, T1.topo_id from cr_business_template T1 left join cr_single_template T2 on T1.resource_id = T2.business_template_id left join cr_single_room R1 on T1.resource_id = R1.business_template_id and R1.user_id = #{user_id}
T1.business_type = #{business_type}
and T2.sub_type = #{category}
and T1.difficulty = #{difficult}
and T1.name like #{pattern}
order by T1.name

select business_template_id, date_format(start_time, '%m-%d') as `date`, count(date_format(start_time, '%m-%d'))
as `count` from cr_train_record
where business_type = #{business_type}
and business_template_id in

    #{template_id}

and date_format(start_time, '%Y-%m-%d') in
#{date_item}
group by business_template_id, date_format(start_time, '%m-%d');

select count(id)
from cr_single_room
where user_id = #{userId}

select  T1.business_template_id, T1.start_time,T1.end_time
from cr_train_record T1, cr_business_template T2
where T1.business_template_id = T2.resource_id
and T1.user_id = #{userId}
and T1.extra is not null
and T1.business_type = #{type}
union select business_template_id , start_time, end_time
from cr_single_room
where user_id = #{userId}
and end_time is null
